package vercelworkflow

import (
	"bytes"
	"context"
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"os/exec"
	"path/filepath"
	"testing"
	"time"
)

// Execute the actual deployable Node functions with proofs generated by Go.
// The generated fixture value and all child diagnostics stay inside the test
// process; neither the child protocol nor failure messages return them.
func TestActualNodeFixtureConsumptionContract(t *testing.T) {
	node, err := exec.LookPath("node")
	if err != nil {
		t.Fatal("Node is required to verify the deployable acceptance fixture")
	}
	secret := make([]byte, 48)
	if _, err = rand.Read(secret); err != nil {
		t.Fatal("fixture randomness unavailable")
	}
	defer wipeBytes(secret)
	value := base64.RawURLEncoding.EncodeToString(secret)
	challengeBytes := make([]byte, 32)
	if _, err = rand.Read(challengeBytes); err != nil {
		t.Fatal("challenge randomness unavailable")
	}
	challenge := base64.RawURLEncoding.EncodeToString(challengeBytes)
	proof := AcceptanceProof([]byte(value), challenge)
	wrong := AcceptanceProof([]byte("independent-wrong-fixture-value"), challenge)
	cases := []struct {
		name, file, method, value, challenge, proof string
		status                                      int
	}{
		{"matching", "envbank-acceptance.js", "GET", value, challenge, proof, FixtureMatch},
		{"wrong-proof", "envbank-acceptance.js", "GET", value, challenge, wrong, FixtureMismatch},
		{"missing-value", "envbank-acceptance.js", "GET", "", challenge, proof, FixtureAbsent},
		{"short-value", "envbank-acceptance.js", "GET", "too-short", challenge, proof, FixtureAbsent},
		{"malformed-challenge", "envbank-acceptance.js", "GET", value, "bad", proof, 400},
		{"malformed-proof", "envbank-acceptance.js", "GET", value, challenge, "bad", 400},
		{"method", "envbank-acceptance.js", "POST", value, challenge, proof, 405},
		{"health", "health.js", "GET", value, challenge, proof, 200},
		{"health-unconfigured", "health.js", "GET", "", challenge, proof, 503},
	}
	const program = `
const fs = require('node:fs');
const input = JSON.parse(fs.readFileSync(0, 'utf8'));
const emit = process.stdout.write.bind(process.stdout);
let observations = 0;
process.stdout.write = () => { observations++; return true; };
process.stderr.write = () => { observations++; return true; };
for (const key of ['log','error','warn','info','debug','dir','trace']) console[key] = () => { observations++; };
try {
 process.env.ENVBANK_ACCEPTANCE_FIXTURE_SECRET = input.value;
 const handler = require(process.argv[1]);
 const headers = {};
 let bytes = 0;
 const response = {
  statusCode: 0,
  setHeader: (key,value) => { headers[key.toLowerCase()] = String(value); },
  end: body => { if (body !== undefined) bytes += Buffer.byteLength(String(body)); },
 };
 const result = handler({method:input.method, headers:{'x-envbank-acceptance-challenge':input.challenge,'x-envbank-acceptance-proof':input.proof}},response);
 emit(JSON.stringify({status:response.statusCode,bytes,observations,noStore:headers['cache-control']==='no-store',async:!!(result&&typeof result.then==='function')}));
} catch (_) { emit(JSON.stringify({failed:true})); }
`
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			path, e := filepath.Abs(filepath.Join("..", "..", "e2e", "fixtures", "vercel-acceptance", "api", c.file))
			if e != nil {
				t.Fatal("fixture path unavailable")
			}
			raw, e := json.Marshal(map[string]string{"value": c.value, "challenge": c.challenge, "proof": c.proof, "method": c.method})
			if e != nil {
				t.Fatal("fixture input unavailable")
			}
			defer wipeBytes(raw)
			ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
			defer cancel()
			cmd := exec.CommandContext(ctx, node, "-e", program, path)
			cmd.Stdin = bytes.NewReader(raw)
			output, e := cmd.CombinedOutput()
			defer wipeBytes(output)
			if e != nil {
				t.Fatal("deployable fixture execution failed; child diagnostics withheld")
			}
			var result struct {
				Status, Bytes, Observations int
				NoStore, Async, Failed      bool
			}
			if json.Unmarshal(output, &result) != nil || result.Failed || result.Status != c.status || result.Bytes != 0 || result.Observations != 0 || !result.NoStore || result.Async {
				t.Fatal("deployable fixture violated status-only consumption contract; diagnostics withheld")
			}
		})
	}
}
